#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998244353LL;
    long long inv_cache[2000000]; // cache for modular inverses
    bool inv_computed[2000000];

    Mod998() {
        memset(inv_computed, 0, sizeof(inv_computed));
    }

    long long mod_add(long long a, long long b) {
        long long res = a + b;
        if (res >= MOD) res -= MOD;
        return res;
    }

    long long mod_sub(long long a, long long b) {
        long long res = a - b;
        if (res < 0) res += MOD;
        return res;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long smallInv(long long a) {
        // Fermat's little theorem for modular inverse
        return pow_mod(a, MOD - 2);
    }

    long long pow_mod(long long base, long long exp) {
        long long result = 1;
        long long cur = base % MOD;
        while (exp > 0) {
            if (exp & 1) result = (result * cur) % MOD;
            cur = (cur * cur) % MOD;
            exp >>= 1;
        }
        return result;
    }

    long long ncr(long long n, long long r) {
        static vector<long long> fact, inv_fact;
        static bool initialized = false;
        if (!initialized) {
            fact.resize(2000001);
            inv_fact.resize(2000001);
            fact[0] = 1;
            for (int i = 1; i <= 2000000; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }
            inv_fact[2000000] = smallInv(fact[2000000]);
            for (int i = 2000000 - 1; i >= 0; i--) {
                inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD;
            }
            initialized = true;
        }
        if (r < 0 || r > n) return 0;
        return (((fact[n] * inv_fact[r]) % MOD) * inv_fact[n - r]) % MOD;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    Mod998 mod;

    // Precompute inverse of (n + m)
    long long inv_n_plus_m = mod.smallInv(n + m);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long numerator = n - i;
        long long denominator = n + m - i;
        long long inv_denominator = mod.smallInv(denominator);
        p = mod.mult(p, numerator);
        p = mod.mult(p, inv_denominator);
        phaseSize = mod.mod_add(phaseSize, p);
        if (i >= n) break; // To prevent infinite loop if p becomes 0
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long numPhases = mod.mult(m + k, mod.smallInv(k));
        long long term = mod.mult(mod.ncr(n, k), numPhases);
        term = mod.mult(term, phaseSize);
        if ((k & 1) == 1)
            answer = mod.mod_add(answer, term);
        else
            answer = mod.mod_sub(answer, term);
    }

    cout << answer << "\n";

    return 0;
}
